export const tasks = pgTable(
  'tasks',
  {
    id: pk(),
    businessId: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    title: varchar('title', { length: 200 }).notNull(),
    description: text('description'),
    status: taskStatusEnum('status').notNull().default('todo'),
    priority: taskPriorityEnum('priority').notNull().default('medium'),
    customerId: uuid('customer_id').references(() => customers.id, { onDelete: 'set null' }),
    orderId: uuid('order_id').references(() => orders.id, { onDelete: 'set null' }),
    invoiceId: uuid('invoice_id').references(() => invoices.id, { onDelete: 'set null' }),
    assigneeId: uuid('assignee_id').references(() => users.id, { onDelete: 'set null' }),
    dueDate: timestamp('due_date', { withTimezone: true }),
    recurrence: varchar('recurrence', { length: 20 }).notNull().default('none'),
    completedAt: timestamp('completed_at', { withTimezone: true }),
    createdByUserId: uuid('created_by_user_id'),
    source: activitySourceEnum('source').notNull().default('user'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('tasks_business_status_idx').on(t.businessId, t.status),
    index('tasks_business_due_idx').on(t.businessId, t.dueDate),
    index('tasks_customer_idx').on(t.customerId),
  ],
);

export const appointments = pgTable(
  'appointments',
  {
    id: pk(),
    businessId: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    title: varchar('title', { length: 200 }).notNull(),
    customerId: uuid('customer_id').references(() => customers.id, { onDelete: 'set null' }),
    productId: uuid('product_id').references(() => products.id, { onDelete: 'set null' }),
    staffId: uuid('staff_id').references(() => users.id, { onDelete: 'set null' }),
    startsAt: timestamp('starts_at', { withTimezone: true }).notNull(),
    durationMinutes: integer('duration_minutes').notNull().default(60),
    status: appointmentStatusEnum('status').notNull().default('scheduled'),
    location: varchar('location', { length: 200 }),
    notes: text('notes'),
    /** Reserved for Google/Outlook sync in Phase 2. */
    externalCalendarId: varchar('external_calendar_id', { length: 200 }),
    createdByUserId: uuid('created_by_user_id'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('appointments_business_start_idx').on(t.businessId, t.startsAt),
    index('appointments_customer_idx').on(t.customerId),
  ],
);

/* -------------------------------------------------------------------------- */
/* Signals: activity, notifications, campaigns, outbox                         */
/* -------------------------------------------------------------------------- */

export const activityEvents = pgTable(
  'activity_events',
  {
    id: pk(),
    businessId: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    type: varchar('type', { length: 60 }).notNull(),
    severity: activitySeverityEnum('severity').notNull().default('info'),
    source: activitySourceEnum('source').notNull().default('system'),
    title: varchar('title', { length: 200 }).notNull(),
    description: text('description'),
    entityType: varchar('entity_type', { length: 40 }),
    entityId: uuid('entity_id'),
    actionLabel: varchar('action_label', { length: 60 }),
    actionHref: varchar('action_href', { length: 200 }),
    actorUserId: uuid('actor_user_id'),
    /** Stable key used to avoid re-emitting the same alert every scan. */
    dedupeKey: varchar('dedupe_key', { length: 160 }),
    readAt: timestamp('read_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    index('activity_events_business_created_idx').on(t.businessId, t.createdAt),
    uniqueIndex('activity_events_dedupe_unique')
      .on(t.businessId, t.dedupeKey)
      .where(sql`${t.dedupeKey} is not null`),
  ],
);

export const notifications = pgTable(
  'notifications',
  {
    id: pk(),
    businessId: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    channel: notificationChannelEnum('channel').notNull().default('in_app'),
    title: varchar('title', { length: 200 }).notNull(),
    body: text('body'),
    severity: activitySeverityEnum('severity').notNull().default('info'),
    href: varchar('href', { length: 200 }),
    readAt: timestamp('read_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('notifications_user_idx').on(t.userId, t.createdAt)],
);

export const campaigns = pgTable(
  'campaigns',
  {
    id: pk(),
    businessId: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    name: varchar('name', { length: 160 }).notNull(),
    channel: varchar('channel', { length: 20 }).notNull().default('email'),
    status: campaignStatusEnum('status').notNull().default('draft'),
    subject: varchar('subject', { length: 200 }),
    body: text('body').notNull(),
    segment: varchar('segment', { length: 60 }),
    audienceCount: integer('audience_count').notNull().default(0),
    audienceIds: jsonb('audience_ids').$type<string[]>().notNull().default(sql`'[]'::jsonb`),
    scheduledFor: timestamp('scheduled_for', { withTimezone: true }),
    sentAt: timestamp('sent_at', { withTimezone: true }),
    createdByUserId: uuid('created_by_user_id'),
    source: activitySourceEnum('source').notNull().default('user'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('campaigns_business_idx').on(t.businessId, t.createdAt)],
);

/**
 * Every outbound message is recorded here before a channel adapter touches it.
 * In development the console adapter marks rows `simulated` — the UI shows them
 * as simulated rather than claiming a real delivery happened.
 */
export const messageOutbox = pgTable(
  'message_outbox',
  {
    id: pk(),
    businessId: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    channel: varchar('channel', { length: 20 }).notNull(),
    provider: varchar('provider', { length: 40 }).notNull(),
    recipient: varchar('recipient', { length: 254 }).notNull(),
    subject: varchar('subject', { length: 200 }),
    body: text('body').notNull(),
    status: varchar('status', { length: 20 }).notNull().default('queued'),
    simulated: boolean('simulated').notNull().default(true),
    error: text('error'),
    campaignId: uuid('campaign_id').references(() => campaigns.id, { onDelete: 'set null' }),
    customerId: uuid('customer_id').references(() => customers.id, { onDelete: 'set null' }),
    sentAt: timestamp('sent_at', { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index('message_outbox_business_idx').on(t.businessId, t.createdAt)],
);

/* -------------------------------------------------------------------------- */
/* AI                                                                          */
/* -------------------------------------------------------------------------- */

export const aiConversations = pgTable(
  'ai_conversations',
  {
    id: pk(),
    businessId: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    title: varchar('title', { length: 200 }).notNull().default('New conversation'),
    agentId: varchar('agent_id', { length: 40 }).notNull().default('chief_of_staff'),
    archivedAt: timestamp('archived_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('ai_conversations_business_user_idx').on(t.businessId, t.userId, t.updatedAt)],
);

export const aiMessages = pgTable(
  'ai_messages',
  {
    id: pk(),
    businessId: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    conversationId: uuid('conversation_id')
      .notNull()
      .references(() => aiConversations.id, { onDelete: 'cascade' }),
    role: aiMessageRoleEnum('role').notNull(),
    content: text('content').notNull(),
    agentId: varchar('agent_id', { length: 40 }),
    /** Recorded tool invocations: name, arguments, duration, redacted result summary. */
    toolCalls: jsonb('tool_calls').$type<unknown[]>().notNull().default(sql`'[]'::jsonb`),
    provider: varchar('provider', { length: 20 }),
    model: varchar('model', { length: 60 }),
    inputTokens: integer('input_tokens'),
    outputTokens: integer('output_tokens'),
    latencyMs: integer('latency_ms'),
    createdAt: createdAt(),
  },
  (t) => [index('ai_messages_conversation_idx').on(t.conversationId, t.createdAt)],
);

/**
 * Consequential tool calls are never executed inline. The model proposes; a row
 * lands here in `proposed`; a human with `ai:approve_actions` decides. Execution
 * happens server-side afterwards and is recorded in ai_action_approvals + audit.
 */
export const aiActions = pgTable(
  'ai_actions',
  {
    id: pk(),
    businessId: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    conversationId: uuid('conversation_id').references(() => aiConversations.id, { onDelete: 'set null' }),
    messageId: uuid('message_id').references(() => aiMessages.id, { onDelete: 'set null' }),
    requestedByUserId: uuid('requested_by_user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    agentId: varchar('agent_id', { length: 40 }).notNull().default('chief_of_staff'),
    tool: varchar('tool', { length: 60 }).notNull(),
    label: varchar('label', { length: 200 }).notNull(),
    description: text('description').notNull(),
    payload: jsonb('payload').$type<Record<string, unknown>>().notNull(),
    preview: jsonb('preview').$type<Array<{ label: string; value: string }>>().notNull().default(sql`'[]'::jsonb`),
    impact: varchar('impact', { length: 10 }).notNull().default('medium'),
    status: aiActionStatusEnum('status').notNull().default('proposed'),
    result: text('result'),
    expiresAt: timestamp('expires_at', { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('ai_actions_business_status_idx').on(t.businessId, t.status, t.createdAt)],
);

export const aiActionApprovals = pgTable(
  'ai_action_approvals',
  {
    id: pk(),
    businessId: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    actionId: uuid('action_id')
      .notNull()
      .references(() => aiActions.id, { onDelete: 'cascade' }),
    decidedByUserId: uuid('decided_by_user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    decision: varchar('decision', { length: 20 }).notNull(),
    note: text('note'),
    createdAt: createdAt(),
  },
  (t) => [index('ai_action_approvals_action_idx').on(t.actionId)],
);

/* -------------------------------------------------------------------------- */
/* Audit                                                                       */
/* -------------------------------------------------------------------------- */

export const auditLogs = pgTable(
  'audit_logs',
  {
    id: pk(),
    businessId: uuid('business_id').references(() => businesses.id, { onDelete: 'cascade' }),
    actorUserId: uuid('actor_user_id').references(() => users.id, { onDelete: 'set null' }),
    actorType: activitySourceEnum('actor_type').notNull().default('user'),
    actorName: varchar('actor_name', { length: 120 }),
    action: varchar('action', { length: 80 }).notNull(),
    entityType: varchar('entity_type', { length: 40 }),
    entityId: uuid('entity_id'),
    summary: text('summary').notNull(),
    metadata: jsonb('metadata').$type<Record<string, unknown>>(),
    ipAddress: varchar('ip_address', { length: 64 }),
    userAgent: text('user_agent'),
    createdAt: createdAt(),
  },
  (t) => [
    index('audit_logs_business_created_idx').on(t.businessId, t.createdAt),
    index('audit_logs_entity_idx').on(t.entityType, t.entityId),
  ],
);

/** Product analytics — activation/engagement/retention, per business. */
export const usageEvents = pgTable(
  'usage_events',
  {
    id: pk(),
    businessId: uuid('business_id').references(() => businesses.id, { onDelete: 'cascade' }),
    userId: uuid('user_id').references(() => users.id, { onDelete: 'set null' }),
    name: varchar('name', { length: 60 }).notNull(),
    properties: jsonb('properties').$type<Record<string, unknown>>(),
    createdAt: createdAt(),
  },
  (t) => [index('usage_events_name_idx').on(t.name, t.createdAt), index('usage_events_business_idx').on(t.businessId, t.createdAt)],
);

/* -------------------------------------------------------------------------- */
/* Relations (used by drizzle's relational query API)                          */
/* -------------------------------------------------------------------------- */

export const usersRelations = relations(users, ({ many }) => ({
  memberships: many(businessMembers),
  sessions: many(sessions),
}));

export const businessesRelations = relations(businesses, ({ many, one }) => ({
  members: many(businessMembers),
  customers: many(customers),
  products: many(products),
  orders: many(orders),
  invoices: many(invoices),
  expenses: many(expenses),
  settings: one(businessSettings, {
    fields: [businesses.id],
    references: [businessSettings.businessId],
  }),
}));

export const businessMembersRelations = relations(businessMembers, ({ one }) => ({
  business: one(businesses, { fields: [businessMembers.businessId], references: [businesses.id] }),
  user: one(users, { fields: [businessMembers.userId], references: [users.id] }),
}));

export const customersRelations = relations(customers, ({ many, one }) => ({
  business: one(businesses, { fields: [customers.businessId], references: [businesses.id] }),
  orders: many(orders),
  invoices: many(invoices),
  tags: many(customerTags),
  events: many(customerEvents),
}));

export const productsRelations = relations(products, ({ many, one }) => ({
  category: one(productCategories, { fields: [products.categoryId], references: [productCategories.id] }),
  movements: many(inventoryMovements),
  orderItems: many(orderItems),
}));

export const ordersRelations = relations(orders, ({ many, one }) => ({
  customer: one(customers, { fields: [orders.customerId], references: [customers.id] }),
  items: many(orderItems),
  payments: many(payments),
}));

export const orderItemsRelations = relations(orderItems, ({ one }) => ({
  order: one(orders, { fields: [orderItems.orderId], references: [orders.id] }),
  product: one(products, { fields: [orderItems.productId], references: [products.id] }),
}));

export const invoicesRelations = relations(invoices, ({ many, one }) => ({
  customer: one(customers, { fields: [invoices.customerId], references: [customers.id] }),
  items: many(invoiceItems),
  payments: many(payments),
}));

export const aiConversationsRelations = relations(aiConversations, ({ many }) => ({
  messages: many(aiMessages),
  actions: many(aiActions),
}));

export const aiActionsRelations = relations(aiActions, ({ many, one }) => ({
  conversation: one(aiConversations, { fields: [aiActions.conversationId], references: [aiConversations.id] }),
  approvals: many(aiActionApprovals),
}));

/* -------------------------------------------------------------------------- */
/* Inferred row types                                                          */
/* -------------------------------------------------------------------------- */

export type User = typeof users.$inferSelect;
export type NewUser = typeof users.$inferInsert;
export type Business = typeof businesses.$inferSelect;
export type BusinessSettingsRow = typeof businessSettings.$inferSelect;
export type BusinessMember = typeof businessMembers.$inferSelect;
export type Customer = typeof customers.$inferSelect;
export type NewCustomer = typeof customers.$inferInsert;
export type Product = typeof products.$inferSelect;
export type NewProduct = typeof products.$inferInsert;
export type Order = typeof orders.$inferSelect;
export type OrderItem = typeof orderItems.$inferSelect;
export type Invoice = typeof invoices.$inferSelect;
export type InvoiceItem = typeof invoiceItems.$inferSelect;
export type Payment = typeof payments.$inferSelect;
export type Expense = typeof expenses.$inferSelect;
export type Task = typeof tasks.$inferSelect;
export type Appointment = typeof appointments.$inferSelect;
export type ActivityEvent = typeof activityEvents.$inferSelect;
export type AiConversation = typeof aiConversations.$inferSelect;
export type AiMessage = typeof aiMessages.$inferSelect;
export type AiAction = typeof aiActions.$inferSelect;
export type AuditLog = typeof auditLogs.$inferSelect;
